import{createFrameLighting}from'./frame-lighting.mjs';
import{prepareBirdRegion}from'./provider.mjs';import{BIRD}from'./registration.mjs';
const MANIFEST_SHA='3f337223b51724f825810ff0a15a6eecbb02897a1202f836342f35a9272ff4cc';const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(v=>v.toString(16).padStart(2,'0')).join('');
const direction={down:'FRONT',right:'RIGHT',left:'LEFT',up:'BACK'},bindings={ROUTE_S2_02:'ECO_STUDENT_F_BASE',ROUTE_S2_04:'LOCAL_WALKER_F_VAR01',ROUTE_S2_05:'LOCAL_WALKER_M_VAR01',ROUTE_S2_06:'ECO_STUDENT_M_BASE',ROUTE_S2_07:'ANGLER_F_BASE',ROUTE_S2_08:'LOCAL_WALKER_M_VAR01'},actors=[...Object.entries(BIRD.actors).map(([id,foot])=>({id,foot,sprite:bindings[id],facing:'down'})),{id:'HARIN_WIND_COMPANION',foot:[1410,210],sprite:'HARIN',facing:'up'}],ids=[...new Set(actors.map(a=>a.sprite))];
// NEW_REBUILD: exact approved source63 atlas frames; no generated actor, altered identity, or progression.
export async function prepareBirdPresentation({signal,appearance='boy'}={}){
 if(!['boy','girl'].includes(appearance))throw Error('BIRD_PRESENTATION_SELECTION');let disposed=false,provider,native,actorCanvas,lastFrame=null,lastPose=null;const shade=createFrameLighting({nightTint:[.32,.39,.56]});const images=new Map;const check=()=>{if(disposed||signal?.aborted)throw Error('BIRD_PRESENTATION_ABORT')};
 const dispose=()=>{if(disposed)return;disposed=true;lastFrame=null;lastPose=null;provider?.dispose();for(const im of images.values())im.close();images.clear();if(native)native.width=native.height=1;native=null;if(actorCanvas)actorCanvas.width=actorCanvas.height=1;actorCanvas=null;signal?.removeEventListener('abort',dispose)};
 const read=async(url,pin)=>{check();const res=await fetch(url,{signal});if(!res.ok)throw Error('BIRD_ATLAS_HTTP');const bytes=await res.arrayBuffer();check();if(await hash(bytes)!==pin)throw Error('BIRD_ATLAS_PIN');return bytes};
 try{provider=await prepareBirdRegion({signal});const manifestURL=new URL('../../assets/approved-atlases/manifest.json',import.meta.url),manifest=JSON.parse(new TextDecoder().decode(await read(manifestURL,MANIFEST_SHA))),playerId=appearance==='girl'?'PLAYER_FEMALE':'PLAYER_MALE';
 for(const key of[...ids.map(x=>'npc/'+x),'player/'+playerId]){const pin=manifest.atlases[key],bytes=await read(new URL('../../'+pin.src,import.meta.url),pin.sha256),image=await createImageBitmap(new Blob([bytes],{type:'image/png'}));if(disposed||signal?.aborted){image.close();throw Error('BIRD_PRESENTATION_ABORT')}images.set(key,image)}
 check();native=new OffscreenCanvas(960,540);const ctx=native.getContext('2d');signal?.addEventListener('abort',dispose,{once:true});
 function actor(key,kind,foot,facing,step,nightMix){const frame=manifest.frames[kind][`${key}.${direction[facing]}.${step}`];if(!frame)throw Error('BIRD_ACTOR_FRAME');const sc=80/192;if(!actorCanvas)actorCanvas=new OffscreenCanvas(frame.width,frame.height);actorCanvas.width=frame.width;actorCanvas.height=frame.height;const ac=actorCanvas.getContext('2d');ac.drawImage(images.get(frame.atlas),...frame.rect,0,0,frame.width,frame.height);const pixels=ac.getImageData(0,0,frame.width,frame.height);shade(pixels.data,pixels.data,nightMix);ac.putImageData(pixels,0,0);ctx.drawImage(actorCanvas,foot[0]-frame.anchor[0]*sc,foot[1]-frame.anchor[1]*sc,frame.width*sc,frame.height*sc)}
 function draw(destination,{foot,facing,elapsedMs=0,moving=false,nightMix=0,lightsEnabled=true,npcFacings={},windCompanion=false}={}){lastFrame=null;lastPose=null;if(disposed)return false;provider.describe(foot,facing);if(!Number.isFinite(elapsedMs)||elapsedMs<0)throw Error('BIRD_TIME');const w=destination.canvas.width,h=destination.canvas.height,cx=Math.floor(Math.max(0,Math.min(BIRD.size[0]-w,foot[0]-w/2))),cy=Math.floor(Math.max(0,Math.min(BIRD.size[1]-h,foot[1]-h/2)));native.width=w;native.height=h;provider.draw(ctx,{camera:[cx,cy,w,h],elapsedMs,nightMix,lights:lightsEnabled});const list=actors.filter(a=>a.id!=='HARIN_WIND_COMPANION'||windCompanion).map(a=>({...a,key:a.sprite,kind:'npc',facing:direction[npcFacings[a.id]]?npcFacings[a.id]:a.facing,step:'IDLE'}));list.push({key:playerId,kind:'player',foot:[...foot],facing,step:moving?['A','IDLE','B','IDLE'][Math.floor(elapsedMs/140)%4]:'IDLE'});list.sort((a,b)=>a.foot[1]-b.foot[1]);for(const a of list)if(a.foot[0]>=cx-100&&a.foot[0]<=cx+w+100&&a.foot[1]>=cy-100&&a.foot[1]<=cy+h+100)actor(a.key,a.kind,[a.foot[0]-cx,a.foot[1]-cy],a.facing,a.step,nightMix);destination.save();try{destination.imageSmoothingEnabled=false;destination.clearRect(0,0,w,h);destination.drawImage(native,0,0)}finally{destination.restore()}lastPose=provider.describe(foot,facing);lastFrame=Object.freeze({});return true}

 return Object.freeze({get pinsVerified(){return!disposed},currentFrame:()=>lastFrame,frameMatchesPose:(token,pose)=>{if(disposed||!lastFrame||token!==lastFrame||!provider.validate(pose))return false;return pose.foot[0]===lastPose.foot[0]&&pose.foot[1]===lastPose.foot[1]&&pose.facing===lastPose.facing},registration:provider.registration,safe:provider.safe,validate:provider.validate,describe:provider.describe,contact:provider.contact,resolveContact:provider.resolveContact,wildZone:provider.wildZone,draw,dispose});
 }catch(e){dispose();throw e}
}
